'use client'

import { useStrings, type StringsOverrides } from './strings'

import * as React from 'react'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Nav, and `tsc --noEmit` passes on it, so the
// gate cannot catch it.
import './nav.css'

// And the shared rule sets, which carry the theme's press gesture. Every
// destination applies `.gs-pressable`, and without this import a customer
// receives the file and the class matches nothing. See
// ./gamestage-primitives.css. GSUI-118.
import './gamestage-primitives.css'
import { LockGlyph } from './glyphs'

/**
 * Nav: the places a player can go from here.
 *
 * Specimen 5a. Four presentations of one component: a bar at the foot of the
 * screen with a mark over each word, a strip of tabs with a rule under the
 * current one, a tray of pills, and a drawer of rows that can say why a place
 * is shut.
 *
 * Each destination rides on `data-gs-nav`, which is deliberately not
 * `data-gs-choice` and not `data-gs-item`: a test counting the options in a
 * question must not also count a nav bar, and browsing a collection is a third
 * thing again. `data-gs-active` is where the player is, which is not
 * `data-gs-selected`, because a destination is not a pick the player may
 * reverse.
 *
 * It performs nothing. It does not navigate, change a route, or decide which
 * destination is current. `onNavigate` reports the press and the host owns
 * everything behind it, including which one is active on the next render.
 */

export interface Destination {
  /** The host's own id. Rides on `data-gs-nav` and comes back to `onNavigate`. */
  id: string
  /** The word a player reads, and the accessible name whatever the treatment. */
  label: string
  /** The mark for it. Inline SVG taking `currentColor`, never a colour emoji. */
  icon?: React.ReactNode
  /** Where the player is now. */
  active?: boolean
  /** Not available at all. Goes flat and takes no focus. */
  disabled?: boolean
  /** Available later, not now. Keeps its shape, shows a padlock, stays focusable. */
  locked?: boolean
  /**
   * Why it refuses, in words: "opens Friday", "closed". Rendered beside the
   * label as the `note` part and read into the accessible name. The
   * reason lives here and never in the label, so the label stays the name of
   * the place. Shown in the drawer, where a row has the room for it.
   */
  note?: string
}

export interface NavProps
  extends Omit<React.HTMLAttributes<HTMLElement>, 'children' | 'onSelect'> {
  /** Per-instance vocabulary, merged over the provider. */
  strings?: StringsOverrides

  /** The places, in the order they are shown. */
  destinations: Destination[]
  /**
   * Which treatment is rendering.
   *
   * `bar` is the foot of the screen, marks with the words underneath; four
   * destinations at most before it drops the words. `tabs` is a strip with a
   * rule under the current one. `pills` is a tray of rounded controls that
   * scrolls sideways. `drawer` is a vertical list whose rows carry a note.
   */
  presentation?: 'bar' | 'tabs' | 'pills' | 'drawer'
  /** Where it sits within its container. */
  placement?: 'top' | 'bottom' | 'left' | 'right'
  /** Called with the destination's id. The component navigates nothing itself. */
  onNavigate?: (id: string) => void
  /** The word a player reads as this nav's name. */
  label?: string
}

/** From the contract's table of state words, so no component invents its own. */

export function Nav(props: NavProps) {
  const { strings, ...componentProps } = props
  const copy = useStrings(strings)
  const STATE_WORD = {
    active: copy['nav.current'],
    locked: copy['nav.locked'],
  } as const
  const {
    destinations,
    presentation = 'bar',
    placement,
    onNavigate,
    label = copy['nav.label'],
    className,
    ...rest
  } = componentProps

  return (
    <nav
      {...rest}
      className={['gs-nav', className].filter(Boolean).join(' ')}
      data-gs-component="nav"
      data-gs-presentation={presentation}
      data-gs-placement={placement}
      aria-label={label}
    >
      <div className="gs-nav__list" data-gs-scope="nav" data-gs-part="list">
        {destinations.map((destination) => {
          // Locked keeps its place in the tab order: "available later" is
          // something a player should be able to reach and hear described.
          // Only disabled, which is not coming back on this surface, leaves.
          // Disabled wins when both are set, the same way button resolves it.
          const isLocked = Boolean(destination.locked) && !destination.disabled
          const unpressable = Boolean(destination.disabled) || isLocked

          // The name carries the state and the reason, because a screen reader
          // user gets no fill, no rule, no padlock and no note.
          const words = [destination.label]
          if (destination.active) words.push(STATE_WORD.active)
          if (isLocked) words.push(STATE_WORD.locked)
          if (destination.note) words.push(destination.note)

          return (
            <button
              key={destination.id}
              type="button"
              // No `gs-action-type`: 5a draws every nav label in the interface
              // face at the label weight, never in the action face. The
              // exemption and its reason are in tests/lib/check-theme-axes.mjs.
              className="gs-nav__destination gs-pressable"
              data-gs-scope="nav" data-gs-part="destination"
              data-gs-nav={destination.id}
              data-gs-active={destination.active ? 'true' : undefined}
              data-gs-disabled={destination.disabled ? 'true' : undefined}
              data-gs-locked={isLocked ? 'true' : undefined}
              // The control travels on press, so it is motion and stops dead
              // under reduced motion. The current treatment is colour, a plate
              // and a rule, which are emphasis and survive.
              data-gs-animates="motion"
              aria-current={destination.active ? 'page' : undefined}
              aria-disabled={unpressable ? 'true' : undefined}
              aria-label={words.join(', ')}
              // aria-disabled does not stop an event the way the native
              // attribute does, so an unpressable destination refuses it here.
              // The native attribute is not used, because a disabled button is
              // unreachable and a locked one must stay describable.
              onClick={unpressable ? undefined : () => onNavigate?.(destination.id)}
            >
              {/* The destination's own mark carries no part. `glyph` is
                  reserved for the mark that carries a state without colour,
                  and a home icon is decoration: naming it `glyph` would stop a
                  selector for that part meaning "a state landed here". */}
              {destination.icon ? (
                <span className="gs-nav__icon" aria-hidden="true">
                  {destination.icon}
                </span>
              ) : null}
              {/* aria-hidden: the button's own label above is the accessible
                  name, and announcing the word again would read it twice. */}
              <span className="gs-nav__label" data-gs-scope="nav" data-gs-part="label" aria-hidden="true">
                {destination.label}
              </span>
              {destination.note ? (
                <span className="gs-nav__note" data-gs-scope="nav" data-gs-part="note" aria-hidden="true">
                  {destination.note}
                </span>
              ) : null}
              {isLocked ? (
                <span
                  className="gs-nav__lock"
                  data-gs-scope="nav" data-gs-part="glyph"
                  // Emphasis, not motion: the padlock is what a reduced-motion
                  // player reads instead of the control refusing to travel.
                  data-gs-animates="emphasis"
                  aria-hidden="true"
                >
                  <LockGlyph />
                </span>
              ) : null}
            </button>
          )
        })}
      </div>
    </nav>
  )
}

/* Nav, as specimen 5a draws it. Every value comes from a token; nothing here
   is a literal colour, size, radius, duration or typeface. The one number is
   the note's opacity, which has no token and is a request (see the report on
   GSUI-201).

   The press gesture comes from `.gs-pressable` in packages/tokens/primitives.css,
   which every destination carries. The action type does not: 5a draws every nav
   label in the interface face at the label weight (12/800 in the bar, 14 to
   16/800 in the pills, tabs and drawer), never in the action face, so the
   destination reads the label tokens directly and tests/lib/check-theme-axes.mjs
   carries the exemption with that reason.

   Two private properties carry the idle face, because it differs by
   presentation: a bar or a tab destination at rest is bare, a pill or a drawer
   row at rest is a surface plate with an edge. The state rules below then only
   have to say what changes. */

.gs-nav {
  --gs-nav-idle-fill: var(--gs-color-surface);
  --gs-nav-idle-edge: var(--gs-color-edge);

  display: flex;
  align-items: stretch;
  gap: var(--gs-space-2);
  box-sizing: border-box;
  padding: var(--gs-space-2);
  color: var(--gs-color-ink);
  background: var(--gs-color-surface);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-xl);
}

/* The list is the group a screen reader hears and the handle a test finds. It
   is not a box: the drawing lays destinations straight into the container, so
   the container is the flex parent and the list contributes no box of its own. */
.gs-nav__list {
  display: contents;
}

.gs-nav__destination {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--gs-space-2);
  box-sizing: border-box;
  margin: 0;
  padding: 0 var(--gs-space-3);

  /* The label tokens, and only their face, size and weight. The drawing types
     every destination in sentence case with no tracking, so the label's
     uppercase and letter-spacing are deliberately not read. */
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  line-height: normal;

  color: var(--gs-color-ink-secondary);
  background: var(--gs-nav-idle-fill);
  border: var(--gs-stroke-ui) solid var(--gs-nav-idle-edge);
  border-radius: var(--gs-radius-md);
  cursor: pointer;
}

/* At rest a destination squeezes on press and casts nothing. Only the current
   one rides on the theme's offset base, and it keeps the gesture the primitives
   hand every pressable. Restated under reduced motion below, because a value
   set here beats the primitives' own reduced-motion rule. */
.gs-nav__destination:not([data-gs-active='true']) {
  --gs-press-transform: var(--gs-depth-styles-squeeze-transform);
  --gs-depth-pressable-pressed: none;
}

.gs-nav__icon,
.gs-nav__lock,
.gs-nav__note {
  display: flex;
  line-height: 1;
}

.gs-nav__icon {
  font-size: var(--gs-size-icon-control);
}

/* The padlock is the mark that carries a state, so it is emphasis and keeps
   its transition under reduced motion. It draws at the label size, 1em, which
   is the 12px the bar draws; below 14px a mark needs the small stroke or it
   greys out into its own antialiasing (glyphs.css). */
.gs-nav__lock {
  transition: opacity var(--gs-motion-emphasis) var(--gs-motion-ease-emphasis);
}

.gs-nav__lock .gs-glyph {
  stroke-width: var(--gs-stroke-glyph-small);
}

.gs-nav__label {
  white-space: nowrap;
}

/* Why a destination refuses, in words, beside the label and never in it. Same
   ink as the row, stepped back. */
.gs-nav__note {
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  white-space: nowrap;
  opacity: 0.8;
}

.gs-nav__destination:focus-visible {
  outline: var(--gs-stroke-focus) solid var(--gs-color-selected);
  outline-offset: var(--gs-space-1);
}

/* -- bar: the foot of the screen ------------------------------------------ */
/* A surface with an edge along its top and nothing else: no radius, no side
   or bottom stroke. Destinations share the width, icon over word. */
.gs-nav[data-gs-presentation='bar'] {
  --gs-nav-idle-fill: transparent;
  --gs-nav-idle-edge: transparent;

  width: 100%;
  border-width: 0;
  border-top-width: var(--gs-stroke-ui);
  border-radius: 0;
}

.gs-nav[data-gs-presentation='bar'] .gs-nav__destination {
  flex: 1 1 0;
  flex-direction: column;
  gap: var(--gs-space-1);
  min-width: 0;
  height: var(--gs-size-action-large);
  padding: 0;
}

.gs-nav[data-gs-presentation='bar'] .gs-nav__label {
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* A bar never ellipsises a word. Four destinations of six characters fit at
   390px; a fifth does not, so from five the bar drops its words and shows the
   marks alone. The accessible name is on the control and is unaffected. */
.gs-nav[data-gs-presentation='bar'] .gs-nav__list:has(> :nth-child(5)) .gs-nav__label {
  display: none;
}

.gs-nav[data-gs-presentation='bar'] .gs-nav__lock {
  position: absolute;
  top: var(--gs-space-2);
  right: var(--gs-space-2);
}

/* -- tabs: a rule under the current one ----------------------------------- */
/* No fill and no radius. The strip carries a rule along its foot; the current
   tab carries a thicker one that sits on it. Every tab squeezes on press. */
.gs-nav[data-gs-presentation='tabs'] {
  --gs-nav-idle-fill: transparent;
  --gs-nav-idle-edge: transparent;

  gap: var(--gs-space-1);
  padding: 0;
  background: none;
  border-width: 0;
  border-bottom-width: var(--gs-stroke-ui);
  border-radius: 0;
}

.gs-nav[data-gs-presentation='tabs'] .gs-nav__destination {
  --gs-press-transform: var(--gs-depth-styles-squeeze-transform);
  --gs-depth-pressable-pressed: none;

  /* Never narrower than its words: equal tabs sized from the widest left the
     others a few pixels short, and "Board" became "Boa...". If the row then
     outgrows its container the nav overflows, which is visible and fixable. */
  min-width: max-content;
  height: var(--gs-size-touch-min);
  padding: 0 var(--gs-space-3);
  margin-bottom: calc(-1 * var(--gs-stroke-ui));
  border-width: 0;
  border-bottom-width: var(--gs-stroke-selected);
  border-radius: 0;
}

.gs-nav[data-gs-presentation='tabs'] .gs-nav__icon,
.gs-nav[data-gs-presentation='pills'] .gs-nav__icon {
  font-size: var(--gs-size-icon-utility);
}

/* -- pills: a tray of rounded controls ------------------------------------ */
/* The tray is a pill itself, sized to its contents and scrolling sideways when
   they outgrow the screen. A pill at rest is a surface plate with an edge. */
.gs-nav[data-gs-presentation='pills'] {
  width: max-content;
  max-width: 100%;
  overflow-x: auto;
  scrollbar-width: none;
  border-radius: var(--gs-radius-full);
}

.gs-nav[data-gs-presentation='pills'] .gs-nav__destination {
  flex: none;
  height: var(--gs-size-control-small);
  padding: 0 var(--gs-space-3);
  border-radius: var(--gs-radius-full);
}

/* -- drawer: a vertical list ---------------------------------------------- */
.gs-nav[data-gs-presentation='drawer'] {
  flex-direction: column;
  align-items: stretch;
}

.gs-nav[data-gs-presentation='drawer'] .gs-nav__destination {
  flex: none;
  /* The row does not centre: the label takes the room and pushes the note and
     the padlock to the right, as the drawing lays it out. */
  justify-content: normal;
  gap: var(--gs-space-3);
  width: 100%;
  height: var(--gs-size-action);
  padding: 0 var(--gs-space-3);
}

.gs-nav[data-gs-presentation='drawer'] .gs-nav__label {
  flex: 1;
  text-align: left;
}

/* -- where the player is -------------------------------------------------- */
/* One marker per presentation. Bar, pills and drawer: the interactive plate on
   the theme's base. Tabs: the ink and the rule, nothing else. Written after the
   presentations at the same specificity so the state wins. */
.gs-nav .gs-nav__destination[data-gs-active='true'] {
  color: var(--gs-color-on-accent);
  background: var(--gs-color-interactive);
  border-color: var(--gs-color-edge);
  box-shadow: var(--gs-depth-pressable);
}

/* -- available later, not now --------------------------------------------- */
/* Keeps its shape and shows a padlock: "not yet" against "not ever". */
.gs-nav .gs-nav__destination[data-gs-locked='true'] {
  color: var(--gs-color-ink-secondary);
  background: transparent;
  border-style: dashed;
  border-color: var(--gs-color-edge-high);
  cursor: default;
}

/* -- not available at all ------------------------------------------------- */
/* Flat, per the depth rule, and it does not travel on press. */
.gs-nav .gs-nav__destination[data-gs-disabled='true'] {
  color: var(--gs-color-disabled-ink);
  background: var(--gs-color-disabled);
  border-color: transparent;
  box-shadow: var(--gs-depth-flat);
  cursor: default;
}

/* The current tab. The drawing writes its rule in `reward`, which in arcade is
   a gradient and so an invalid border colour that the browser discards; the
   canvas paints the rule in the ink. The note under the drawing says reward,
   and reward.solid is the token a stroke reads. design/twins/5a.json carries
   the allowance. */
.gs-nav[data-gs-presentation='tabs'] .gs-nav__destination[data-gs-active='true'] {
  color: var(--gs-color-ink);
  background: transparent;
  border-color: var(--gs-color-reward-solid);
  box-shadow: none;
}

/* -- placement ------------------------------------------------------------ */
/* The edge the nav hugs. The host owns the container; a nav on a side runs
   its destinations down rather than across. */
.gs-nav[data-gs-placement='left'],
.gs-nav[data-gs-placement='right'] {
  flex-direction: column;
  align-items: stretch;
}

/* Restated on the element and deliberately last: the squeeze set above beats
   the primitives' own reduced-motion rule, so it has to be zeroed here too. */
/* A destination's press, for a player who has asked for stillness.
 *
 * Every other pressable answers through the shared rule at the bottom of
 * primitives.css, which remaps the edge and the depth tokens. A destination
 * reads neither: it draws from `--gs-nav-idle-fill` and `--gs-nav-idle-edge`,
 * which the bar and the tabs presentations both set to `transparent`, and it
 * casts nothing at all, so with the squeeze gone it answered with nothing.
 * Measured on 20 September. GSUI-164.
 *
 * Specificity is deliberate: `.gs-nav[data-gs-presentation='bar']
 * .gs-nav__destination` is where the transparent values are set, so a rule
 * that only says `.gs-nav__destination:active` would lose to it. */
@media (prefers-reduced-motion: reduce) {
  .gs-nav .gs-nav__destination:active:not([data-gs-disabled='true']):not([data-gs-locked='true']) {
    --gs-nav-idle-fill: var(--gs-color-surface-raised);
    --gs-nav-idle-edge: var(--gs-color-edge-high);
  }
}

@media (prefers-reduced-motion: reduce) {
  /* Matched to the two rules that set the squeeze above, not written at the
     bare class. `.gs-nav__destination:not([data-gs-active='true'])` carries an
     attribute selector and outranks `.gs-nav__destination`, so this rule was
     losing and a destination still squeezed under reduced motion. Measured on
     20 September. GSUI-164. */
  .gs-nav__destination:not([data-gs-active='true']),
  .gs-nav[data-gs-presentation='tabs'] .gs-nav__destination {
    --gs-press-transform: none;
  }
}
